    d = +m[1]; mo = MON[m[2].slice(0, 3).toLowerCase()]; y = +m[3]; rest = m[4] || ''; // 03-Mar-2021
  } else if ((m = s.match(/^([A-Za-z]{3,9})\.? (\d{1,2}),? (\d{4}|\d{2})(?: (.+))?$/))) {
    mo = MON[m[1].slice(0, 3).toLowerCase()]; d = +m[2]; y = +m[3]; rest = m[4] || ''; // Mar 3, 2021
  } else {
    return 'REVIEW';
  }

  if (mo === undefined) return 'REVIEW';
  if (y < 100) y += 2000;

  // Optional time: 9:12, 09:12:30, 9:12 PM
  let h = 0, mi = 0, sec = 0;
  if (rest) {
    const t = rest.trim().match(/^(\d{1,2}):(\d{2})(?::(\d{2}))?\s*([AaPp][Mm])?$/);
    if (!t) return 'REVIEW';
    h = +t[1]; mi = +t[2]; sec = +(t[3] || 0);
    if (t[4]) {
      if (h < 1 || h > 12) return 'REVIEW';
      h = (h % 12) + (/p/i.test(t[4]) ? 12 : 0);
    }
    if (h > 23 || mi > 59 || sec > 59) return 'REVIEW';
  }

  const dt = new Date(y, mo, d, h, mi, sec);
  // Reject rollovers like Feb 30 -> Mar 2
  if (dt.getFullYear() !== y || dt.getMonth() !== mo || dt.getDate() !== d) return 'REVIEW';
  return dt;
}

// Park lookup key: lowercase letters only
function parkKey_(v) {
  return String(v).toLowerCase().replace(/[^a-z]/g, '');
}

// ParkMap: A = key/variant, B = canonical name, header in row 1.
// Keys are re-normalized, so "West-Side" or "W. Side" also work as entries.
function loadParkMap_(ss) {
  const sh = ss.getSheetByName(CFG.MAP);
  if (!sh) throw new Error('Missing sheet: ' + CFG.MAP);
  const map = {};
  const last = sh.getLastRow();
  if (last < 2) return map;
  sh.getRange(2, 1, last - 1, 2).getValues().forEach(([k, canon]) => {
    const key = parkKey_(k);
    const c = String(canon).trim();
    if (key && c) map[key] = c;
  });
  return map;
}

// Raw park -> canonical name; blank or unmapped -> REVIEW
function mapPark_(v, map) {
  const key = parkKey_(v);
  if (!key) return 'REVIEW';
  return map[key] || 'REVIEW';
}

// Groups an array into { key: [items] }
function groupBy_(arr, keyFn) {
  return arr.reduce((acc, x) => {
    const k = keyFn(x);
    (acc[k] = acc[k] || []).push(x);
    return acc;
  }, {});
}

// Clears and rebuilds an output sheet: header row, formats, then data.
// Hard guard: refuses to ever write to Raw.
function writeSheet_(ss, name, rows) {
  if (name === CFG.RAW) throw new Error('Refusing to write to ' + CFG.RAW);
  const sh = ss.getSheetByName(name) || ss.insertSheet(name);
  sh.clear(); // remove previous values and formats

  // Header row
  const nCols = HEADERS.length;
  sh.getRange(1, 1, 1, nCols).setValues([HEADERS]).setFontWeight('bold');
  sh.setFrozenRows(1);
  if (rows.length === 0) return; // headers only

  const n = rows.length;

  // Set formats BEFORE writing values so text stays text:
  // - Columns B:H and J:P as plain text. This keeps Phone_Clean leading
  //   zeros and stops raw entries like "+1 555 1236" being read as formulas.
  // - Column A (raw timestamp) and Q (RawRow) keep automatic formatting.
  sh.getRange(2, 2, n, COL.TS_CLEAN - 2).setNumberFormat('@');               // B:H
  sh.getRange(2, COL.TS_CLEAN + 1, n, COL.RAW_ROW - COL.TS_CLEAN - 1)
    .setNumberFormat('@');                                                   // J:P
  sh.getRange(2, COL.TS_CLEAN, n, 1).setNumberFormat(CFG.TS_FORMAT);         // I = datetime

  // Write all data rows in one call
  sh.getRange(2, 1, n, nCols).setValues(rows);

  sh.autoResizeColumns(1, nCols);
}

// ===== END OF SCRIPT =====
```

## Notes

- **Raw is never modified.** The script only reads from Raw, and `writeSheet_` throws an error if it's ever pointed at Raw.
- **Time zone:** Parsed text timestamps use the script's time zone. If Timestamp_Clean values look shifted by a few hours, go to **Project Settings (gear icon)** in the editor and set the time zone to match **File > Settings** in the spreadsheet.
- **SUPERSEDED rows** land in Review, because any duplicate triggers review. While reviewing, filter `Superseded = SUPERSEDED` to see the copies you'd drop.
- **Formula columns:** If you still have the G–P formula columns from earlier on Raw, they're unaffected. The script only reads A:F.
